-- CMC public website content managed from CMC Pathway.
-- Run once in the Supabase SQL editor, then open Website in CMC Pathway.

create table if not exists public.cmc_public_content (
  content_key text primary key check (content_key in ('team','resources','models','discern')),
  draft_data jsonb not null default '{}'::jsonb,
  published_data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  published_at timestamptz,
  updated_by uuid references auth.users(id) on delete set null,
  published_by uuid references auth.users(id) on delete set null
);

alter table public.cmc_public_content enable row level security;
revoke all on public.cmc_public_content from anon, authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('cmc-public-media','cmc-public-media',true,4194304,array['image/jpeg','image/png','image/webp','image/avif'])
on conflict (id) do update set
  public=true,
  file_size_limit=4194304,
  allowed_mime_types=array['image/jpeg','image/png','image/webp','image/avif'];

drop policy if exists "Public can view CMC website media" on storage.objects;
create policy "Public can view CMC website media" on storage.objects
for select to public using (bucket_id = 'cmc-public-media');

-- Writes intentionally have no browser policy. Netlify functions use the service role.

-- Seed the current public-site content without overwriting future edits.
